window.AAQ_ASSIGN = {"unit": 5, "title": "Biomedical Science", "aims": [{"aim": "A", "title": "Understand the principles of haematology and its use in medical diagnosis"}, {"aim": "B", "title": "Examine the use of, histology, cytology and disease screening"}, {"aim": "C", "title": "Examine the use of urinalysis as an analytical and diagnostic tool"}], "criteria": [{"code": "A.P1", "aims": "A", "grade": "P", "n": 1, "text": "Describe the structure and function of the main components of blood."}, {"code": "A.P2", "aims": "A", "grade": "P", "n": 2, "text": "Describe how diseases affect the composition of blood and how the changes are identified by blood testing."}, {"code": "A.M1", "aims": "A", "grade": "M", "n": 1, "text": "Explain the procedures used in diagnostic tests for different diseases."}, {"code": "A.D1", "aims": "A", "grade": "D", "n": 1, "text": "Evaluate the use of diagnostic testing of blood in relation to the detection of diseases."}, {"code": "B.P3", "aims": "B", "grade": "P", "n": 3, "text": "Describe the use of analytical investigation in disease screening."}, {"code": "B.P4", "aims": "B", "grade": "P", "n": 4, "text": "Describe the use of analytical investigations of cell and tissue samples."}, {"code": "B.M2", "aims": "B", "grade": "M", "n": 2, "text": "Explain the importance of accurate and timely diagnoses on treatment outcomes."}, {"code": "B.D2", "aims": "B", "grade": "D", "n": 2, "text": "Evaluate the implications of screening and early disease diagnosis for the individual and for the health service."}, {"code": "C.P5", "aims": "C", "grade": "P", "n": 5, "text": "Describe how urine composition may vary in relation to health."}, {"code": "C.P6", "aims": "C", "grade": "P", "n": 6, "text": "Correctly carry out simple urinalysis."}, {"code": "C.M3", "aims": "C", "grade": "M", "n": 3, "text": "Explain the causes of the results of urinalysis used in diagnoses of health status changes."}, {"code": "C.D3", "aims": "C", "grade": "D", "n": 3, "text": "Evaluate the use of urinalysis in domestic and clinical settings."}], "guidance": [{"aims": "A", "paras": ["For distinction standard, students must make judgements about the appropriate selection, implementation, and interpretation of diagnostic tests by medical workers and clearly link the disease and blood composition. They will give a detailed consideration of the implications of misdiagnosis of disease, with the accurate use of appropriate scientific terminology throughout. For merit standard, students must explain how diagnostic tests are used when investigating two different diseases. They will refer to required equipment and techniques used in each diagnostic test. They must include detail of changes to the composition of blood with reference to normal ranges in humans. For pass standard, students must link the structure and function of each of the main components of blood. For diseases associated with dysfunction or abnormality of blood components they must state the specific effects on blood composition, and how the changes/effects are identified through haematological examination."]}, {"aims": "B", "paras": ["For distinction standard, students must evaluate the importance of early diagnosis leading to treatment and the implications of this, including a consideration of the associated emotional and financial costs to the individual and their families, and the financial cost to health services. Students must demonstrate an understanding of the importance of accurately sampling and reporting diagnostic results including the potential implications of false positive and false negative results. For merit standard, students must provide an explanation of the importance of correct and timely diagnosis in the treatment of, and prognosis for, the individual. This will include an awareness of how tissue analysis can be enhanced using automated sampling. For pass standard, students must describe different screening techniques and their role in early detection of disease. They must describe how cells and tissue samples are removed for examination and the appearance of normal and abnormal results. They must describe the implications of inaccurate test results."]}, {"aims": "C", "paras": ["For distinction standard, students must evaluate the clinical techniques used in relation to urine sample collection, preservation, and analysis in domestic and clinical settings. They must consider the implications of inaccuracies in results and in their interpretation and how errors can be reduced. For merit standard, students must explain how the results of urinalysis indicate the presence of disease. They must explain how the changes caused by disease lead to the results seen in specific diseases. They will explain how contamination when collecting or preserving urine samples can cause inaccurate results. For pass standard, students will provide the normal values for the composition of urine in health and describe how these are affected by specific disease processes. Students must specify how samples of urine should be obtained to prevent misleading results. Students will carry out simple urinalysis, accurately identifying any abnormality in samples of urine and suggesting what these abnormalities indicate in relation to health. Students will carry out a risk assessment before carrying out their urinalysis."]}]};
